// Pega os pipelines e o lead atual
const pipelines = $('BUSCA FUNIS DE VENDAS E ESTÁGIOS').first().json._embedded.pipelines;
const lead = $('BUSCA LEAD').first().json;

// Busca o pipeline atual pelo ID do lead
const pipelineAtual = pipelines.find(p => p.id === lead.pipeline_id);

// Se encontrou o pipeline, busca o estágio atual
const statusAtual = pipelineAtual?._embedded?.statuses.find(s => s.id === lead.status_id);

// Retorna o nome do funil e do estágio
return [
  {
    json: {
      pipeline_id: lead.pipeline_id,
      pipeline_nome: pipelineAtual?.name || 'Desconhecido',
      status_id: lead.status_id,
      estagio_nome: statusAtual?.name || 'Desconhecido'
    }
  }
];

